begin;
select plan(15);
insert into auth.users(id) values('eeeeeeee-eeee-4eee-8eee-eeeeeeeeee01'),('eeeeeeee-eeee-4eee-8eee-eeeeeeeeee02');
select ok((select relrowsecurity from pg_class where oid='public.tutor_attempt_limits'::regclass),'Attempt counter has RLS');
set local role authenticated;
select throws_ok($$select * from public.tutor_attempt_limits$$,'42501',null,'Clients cannot enumerate counters');
select throws_ok($$select public.consume_tutor_attempt('eeeeeeee-eeee-4eee-8eee-eeeeeeeeee02')$$,'42501',null,'Clients cannot exhaust another account budget');
select throws_ok($$select public.retain_tutor_attempt_limits()$$,'42501',null,'Clients cannot reset counters');
set local role service_role;
select is((select count(*)::int from generate_series(1,30) where (public.consume_tutor_attempt('eeeeeeee-eeee-4eee-8eee-eeeeeeeeee01')->>'allowed')::boolean),30,'Thirty grading admissions per account and minute');
select is(public.consume_tutor_attempt('eeeeeeee-eeee-4eee-8eee-eeeeeeeeee01')->>'allowed','false','Thirty-first grading request is refused');
select ok((public.consume_tutor_attempt('eeeeeeee-eeee-4eee-8eee-eeeeeeeeee01')->>'retryAfter')::int between 1 and 60,'Retry delay is bounded');
select is((select requests from public.tutor_attempt_limits where user_id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeee01'),30,'Refusals do not grow an unbounded counter');
select is(public.consume_tutor_attempt('eeeeeeee-eeee-4eee-8eee-eeeeeeeeee02')->>'allowed','true','Another account has an independent budget');
update public.tutor_attempt_limits set window_started_at=clock_timestamp()-interval '61 seconds' where user_id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeee01';
select is(public.consume_tutor_attempt('eeeeeeee-eeee-4eee-8eee-eeeeeeeeee01')->>'allowed','true','An elapsed window starts a fresh budget');
select is((select requests from public.tutor_attempt_limits where user_id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeee01'),1,'Fresh window starts with one admission');
update public.tutor_attempt_limits set window_started_at=clock_timestamp()-interval '2 days' where user_id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeee01';
select is(public.retain_tutor_attempt_limits()->>'changed','1','Retention removes expired security metadata');
select is((select count(*)::int from public.tutor_attempt_limits),1,'Retention preserves the current budget');
reset role;
delete from auth.users where id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeee02';
select is((select count(*)::int from public.tutor_attempt_limits),0,'Account deletion cascades to the counter');
select is((select count(*)::int from public.tutor_requests where user_id='eeeeeeee-eeee-4eee-8eee-eeeeeeeeee01'),0,'Grading admissions create no model requests');
select * from finish();
rollback;
